t.script:
var hasGps = false;

function captureLocation() {
    var btn = document.getElementById('btnCaptureGPS');
    var status = document.getElementById('gpsStatusText');
    var display = document.getElementById('gpsCoordsDisplay');
    var submitBtn = document.getElementById('btnSubmitAttendance');

    btn.disabled = true;
    status.innerText = 'Detecting GPS signal...';

    FFM.captureGPS(
        function(pos) {
            btn.disabled = false;
            document.getElementById('latitude').value = pos.latitude.toFixed(7);
            document.getElementById('longitude').value = pos.longitude.toFixed(7);
            document.getElementById('accuracy').value = pos.accuracy.toFixed(1);

            hasGps = true;
            status.innerHTML = 'Location captured successfully!';
            status.style.color = 'var(--ffm-success)';
            display.style.display = 'block';
            display.innerText = 'Lat: ' + pos.latitude.toFixed(5) + ', Lon: ' + pos.longitude.toFixed(5) + ' (Accuracy: ±' + Math.round(pos.accuracy) + 'm)';
            submitBtn.disabled = false;
        },
        function(err) {
            btn.disabled = false;
            hasGps = false;
            submitBtn.disabled = true;
            status.innerText = 'Error: ' + err.message;
            status.style.color = 'var(--ffm-danger)';
            FFM.showToast(err.message, 'error');
        }
    );
}

function handleAttendanceSubmit(e) {
    e.preventDefault();
    if (!hasGps) {
        FFM.showToast('Please capture your GPS location first.', 'error');
        return false;
    }

    var submitBtn = document.getElementById('btnSubmitAttendance');
    var release = FFM.doubleTapGuard(submitBtn, 'Submitting attendance...');

    var payload = {
        latitude: parseFloat(document.getElementById('latitude').value),
        longitude: parseFloat(document.getElementById('longitude').value),
        accuracy: parseFloat(document.getElementById('accuracy').value),
        mode_of_journey: document.getElementById('mode_of_journey').value,
        client_uuid: FFM.getOrGenerateUUID('ffm_attendance_uuid')
    };

    fetch('/ff/attendance/submit', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({params: payload})
    })
    .then(function(res) {
        return res.json();
    })
    .then(function(data) {
        var res = data.result || data;
        if (res.status === 'success') {
            FFM.clearDraft('attendance');
            FFM.resetUUID('ffm_attendance_uuid');
            FFM.showToast(res.message || 'Attendance submitted successfully!', 'success');
            setTimeout(function() {
                window.location.reload();
            }, 1200);
        } else {
            release();
            FFM.showToast(res.message || 'Failed to submit attendance.', 'error');
        }
    })
    .catch(function(err) {
        release();
        FFM.showToast('Network connection error. Please try again.', 'error');
    });

    return false;
}

function submitDailyReport() {
    if (!confirm('Are you sure you want to finalize and submit today\'s report? Changes cannot be made after submission.')) {
        return;
    }
    var btn = document.getElementById('btnSubmitReport');
    var release = FFM.doubleTapGuard(btn, 'Submitting...');

    fetch('/ff/report/daily/submit', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({params: {}})
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
        var res = data.result || data;
        if (res.status === 'success') {
            FFM.showToast(res.message, 'success');
            setTimeout(function() { window.location.reload(); }, 1200);
        } else {
            release();
            FFM.showToast(res.message, 'error');
        }
    })
    .catch(function(err) {
        release();
        FFM.showToast('Network error. Please try again.', 'error');
    });
}

function handleInitReport(e) {
    e.preventDefault();
    var placeId = document.getElementById('working_place_id').value;
    if (!placeId) {
        FFM.showToast('Please select a working place.', 'error');
        return false;
    }
    var btn = document.getElementById('btnInitReport');
    var release = FFM.doubleTapGuard(btn, 'Processing...');

    fetch('/ff/report/daily/init', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({params: {working_place_id: placeId}})
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
        var res = data.result || data;
        if (res.status === 'success') {
            FFM.showToast(res.message, 'success');
            setTimeout(function() { window.location.reload(); }, 1000);
        } else {
            release();
            FFM.showToast(res.message, 'error');
        }
    })
    .catch(function(err) {
        release();
        FFM.showToast('Network error. Please try again.', 'error');
    });
    return false;
}

function searchChemists(term) {
    if (!term || term.length < 2) return;
    fetch('/ff/api/customers/search', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({params: {type: 'chemist', term: term}})
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
        var res = data.result || data;
        var sel = document.getElementById('chemist_id');
        sel.innerHTML = '<option value="">-- Select --</option>';
        if (res.results) {
            res.results.forEach(function(c) {
                var opt = document.createElement('option');
                opt.value = c.id;
                opt.innerText = c.name + (c.address ? ' (' + c.address + ')' : '');
                sel.appendChild(opt);
            });
        }
    });
}

function checkModeOther(val) {
    document.getElementById('divOtherMode').style.display = (val === 'others') ? 'block' : 'none';
}

function calculateJourney() {
    var pFrom = document.getElementById('place_from_id').value;
    var pTo = document.getElementById('place_to_id').value;
    var mode = document.getElementById('mode').value;

    if (!pFrom || !pTo) {
        FFM.showToast('Please select starting and destination places.', 'error');
        return;
    }

    fetch('/ff/api/journey/calculate', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({params: {place_from_id: pFrom, place_to_id: pTo, mode: mode}})
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
        var res = data.result || data;
        if (res.distance_km !== undefined) {
            document.getElementById('distance_km').value = res.distance_km;
            document.getElementById('fare_tk').value = res.fare_tk;
            FFM.showToast('Distance: ' + res.distance_km + ' km, Fare: Tk ' + res.fare_tk, 'success');
        }
    });
}

function handleChemistSubmit(e) {
    e.preventDefault();
    var chemId = document.getElementById('chemist_id').value;
    var chemManual = document.getElementById('chemist_name_manual').value.trim();

    if (!chemId && !chemManual) {
        FFM.showToast('Please select a chemist or enter a manual name.', 'error');
        return false;
    }

    var order = parseInt(document.getElementById('order_tk').value, 10);
    var sale = parseInt(document.getElementById('sale_tk').value, 10);
    var coll = parseInt(document.getElementById('coll_tk').value, 10);

    if (isNaN(order) || isNaN(sale) || isNaN(coll) || order < 0 || sale < 0 || coll < 0) {
        FFM.showToast('Please enter valid whole numbers for amounts.', 'error');
        return false;
    }

    var btn = document.getElementById('btnSubmitChemist');
    var release = FFM.doubleTapGuard(btn, 'Saving...');

    var payload = {
        chemist_id: chemId || false,
        chemist_name_manual: chemManual || false,
        order_tk: order,
        sale_tk: sale,
        coll_tk: coll,
        note: document.getElementById('note').value.trim(),
        place_from_id: document.getElementById('place_from_id').value,
        place_to_id: document.getElementById('place_to_id').value,
        mode: document.getElementById('mode').value,
        other_mode: document.getElementById('other_mode').value.trim(),
        distance_km: parseFloat(document.getElementById('distance_km').value || 0),
        fare_tk: parseFloat(document.getElementById('fare_tk').value || 0),
        client_uuid: FFM.getOrGenerateUUID('ffm_chemist_visit_uuid')
    };

    fetch('/ff/visit/chemist/submit', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({params: payload})
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
        var res = data.result || data;
        if (res.status === 'success') {
            FFM.resetUUID('ffm_chemist_visit_uuid');
            FFM.showToast(res.message, 'success');
            setTimeout(function() { window.location.href = '/ff/entries/today'; }, 1000);
        } else {
            release();
            FFM.showToast(res.message, 'error');
        }
    })
    .catch(function(err) {
        release();
        FFM.showToast('Network connection error occurred.', 'error');
    });

    return false;
}

