function onAmountChanged(field) {
    var val = parseFloat(document.getElementById(field).value || 0);
    var badgeMap = {
        'entertainment': 'badge_v_ent',
        'courier': 'badge_v_cou',
        'photocopy': 'badge_v_pho',
        'hotel_rent': 'badge_v_hot'
    };
    var badgeId = badgeMap[field];
    if (badgeId) {
        var badge = document.getElementById(badgeId);
        if (badge) {
            badge.style.display = (val > 0) ? 'inline-block' : 'none';
        }
    }
    recalcTotal();
}

function recalcTotal() {
    var fields = ['entertainment', 'courier', 'photocopy', 'hotel_rent', 'promotion', 'stationery', 'carrying', 'banking', 'bike'];
    var total = 0;
    fields.forEach(function(f) {
        var el = document.getElementById(f);
        if (el) {
            var v = parseFloat(el.value || 0);
            if (v > 0) total += v;
        }
    });
    document.getElementById('live_form_total').innerText = Math.round(total);
}

function onFileSelected(inputEl, previewImgId, hiddenInputId) {
    var file = inputEl.files && inputEl.files[0];
    if (!file) return;

    FFM.compressImage(file, function(dataUrl, err) {
        if (err || !dataUrl) {
            FFM.showToast('Failed to process image. Please try again.', 'error');
            inputEl.value = '';
            return;
        }
        document.getElementById(hiddenInputId).value = dataUrl;
        var img = document.getElementById(previewImgId);
        img.src = dataUrl;
        img.parentElement.style.display = 'block';
    }, 1280, 0.7);
}

function clearVoucher(fileInputId, previewImgId, previewBoxId, hiddenInputId) {
    document.getElementById(fileInputId).value = '';
    document.getElementById(hiddenInputId).value = '';
    var img = document.getElementById(previewImgId);
    img.src = '';
    document.getElementById(previewBoxId).style.display = 'none';
}

function handleExpenseSubmit(event) {
    event.preventDefault();

    var entertainment = parseFloat(document.getElementById('entertainment').value || 0);
    var courier = parseFloat(document.getElementById('courier').value || 0);
    var photocopy = parseFloat(document.getElementById('photocopy').value || 0);
    var hotel_rent = parseFloat(document.getElementById('hotel_rent').value || 0);
    var promotion = parseFloat(document.getElementById('promotion').value || 0);
    var stationery = parseFloat(document.getElementById('stationery').value || 0);
    var carrying = parseFloat(document.getElementById('carrying').value || 0);
    var banking = parseFloat(document.getElementById('banking').value || 0);
    var bike = parseFloat(document.getElementById('bike').value || 0);
    var note = document.getElementById('note').value.trim();

    var amounts = [entertainment, courier, photocopy, hotel_rent, promotion, stationery, carrying, banking, bike];
    for (var i = 0; i < amounts.length; i++) {
        if (amounts[i] < 0) {
            FFM.showToast('Expense amount cannot be negative.', 'error');
            return false;
        }
    }

    var total = 0;
    amounts.forEach(function(a) { total += a; });
    if (total <= 0) {
        FFM.showToast('At least one expense category (>0) is required.', 'error');
        return false;
    }

    var v_ent = document.getElementById('hidden_v_ent').value;
    var v_cou = document.getElementById('hidden_v_cou').value;
    var v_pho = document.getElementById('hidden_v_pho').value;
    var v_hot = document.getElementById('hidden_v_hot').value;

    if (entertainment > 0 && !v_ent) {
        FFM.showToast('Entertainment voucher image is required.', 'error');
        return false;
    }
    if (courier > 0 && !v_cou) {
        FFM.showToast('Courier voucher image is required.', 'error');
        return false;
    }
    if (photocopy > 0 && !v_pho) {
        FFM.showToast('Photocopy voucher image is required.', 'error');
        return false;
    }
    if (hotel_rent > 0 && !v_hot) {
        FFM.showToast('Hotel rent voucher image is required.', 'error');
        return false;
    }

    var btn = document.getElementById('submitExpenseBtn');
    var release = FFM.doubleTapGuard(btn, 'Submitting... please wait');
    var clientUuid = FFM.getOrGenerateUUID('ffm_expense_uuid');

    var payload = {
        client_uuid: clientUuid,
        entertainment: entertainment,
        courier: courier,
        photocopy: photocopy,
        hotel_rent: hotel_rent,
        promotion: promotion,
        stationery: stationery,
        carrying: carrying,
        banking: banking,
        bike: bike,
        note: note,
        voucher_entertainment: v_ent,
        voucher_courier: v_cou,
        voucher_photocopy: v_pho,
        voucher_hotel_rent: v_hot
    };

    fetch('/ff/expense/submit', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({params: payload})
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
        var res = data.result || data;
        if (res.status === 'success') {
            FFM.resetUUID('ffm_expense_uuid');
            FFM.showToast(res.message || 'Daily expense submitted successfully.', 'success');
            setTimeout(function() {
                window.location.reload();
            }, 800);
        } else {
            release();
            FFM.showToast(res.message || 'Failed to save expense.', 'error');
        }
    })
    .catch(function(err) {
        release();
        FFM.showToast('Network error. Please try again.', 'error');
    });

    return false;
}

function switchManagerTab(tabName, event) {
    if (event) event.preventDefault();
    document.querySelectorAll('.ffm-tab-pane').forEach(function(el) {
        el.style.display = 'none';
    });
    var target = document.getElementById('tab-' + tabName);
    if (target) target.style.display = 'block';

    document.querySelectorAll('#managerTabsNav .ffm-manager-tab-btn').forEach(function(btn) {
        btn.classList.remove('active');
        if (btn.getAttribute('data-tab') === tabName) {
            btn.classList.add('active');
        }
    });

    if (window.history && window.history.replaceState) {
        window.history.replaceState(null, '', '/ff/manager?tab=' + tabName);
    }
}
